import argparse
import os
import sys
import threading
import queue
import time
from concurrent.futures import ThreadPoolExecutor, as_completed

def process_source_path(k, path, out_dir, errors_file):
    try:
        with open(path, 'rb') as src:
            data = src.read()
        dest_path = os.path.join(out_dir, f'copy_{k:04d}.bin')
        with open(dest_path, 'wb') as dst:
            dst.write(data)
        return True, k, path
    except Exception as e:
        return False, k, path

def worker(task_queue, out_dir, errors_file, rate_limit):
    while True:
        try:
            k, path = task_queue.get(timeout=1)
            success, k, path = process_source_path(k, path, out_dir, errors_file)
            if success:
                print(f"OK {k} {path}")
            else:
                print(f"FAIL {k} {path}")
                with open(errors_file, 'a') as f:
                    f.write(f"{path}\n")
            task_queue.task_done()
        except queue.Empty:
            continue

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--out', required=True, help='Output directory')
    parser.add_argument('--workers', type=int, default=4, help='Number of workers')
    parser.add_argument('--rate', type=int, default=1, help='Operations per second')
    args = parser.parse_args()

    out_dir = args.out
    os.makedirs(out_dir, exist_ok=True)
    errors_file = os.path.join(out_dir, 'errors.log')

    source_paths = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            source_paths.append(line)

    task_queue = queue.Queue()
    rate_limiter = queue.Limiter(args.rate)

    with ThreadPoolExecutor(max_workers=args.workers) as executor:
        futures = []
        for k, path in enumerate(source_paths, 1):
            if rate_limiter.acquire(blocking=False):
                task_queue.put((k, path))
                futures.append(executor.submit(lambda q, k, p: q.put((k, p)), task_queue, k, path))

        for future in as_completed(futures):
            try:
                k, path = future.result()
                rate_limiter.release()
            except Exception:
                pass

        while not task_queue.empty():
            time.sleep(0.1)

        for worker_thread in executor._threads:
            worker_thread.join()

if __name__ == "__main__":
    main()
